import { useState } from "react";
import { Shadcn as S } from "materialfluid";

export function Example() {
  const [ratio, setRatio] = useState(16 / 9);
  const sampleMedia = "data:image/svg+xml," + encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="800" viewBox="0 0 1200 800"><rect width="1200" height="800" fill="#dce8e0"/><circle cx="860" cy="210" r="100" fill="#f3d895"/><path d="M0 620 320 180 650 680 920 320 1200 610V800H0Z" fill="#879d8d"/><path d="M0 770 400 430 760 800 1040 510 1200 700V800H0Z" fill="#41594f"/><path d="M430 800 590 585 700 800" fill="#b6c9c0"/></svg>`);
  const ratioControl = <S.Select label="Aspect ratio" value={String(ratio)} onValueChange={value=>setRatio(Number(value))} options={[{value:String(16/9),label:"Video · 16:9"},{value:String(4/3),label:"Photo · 4:3"},{value:"1",label:"Square · 1:1"},{value:String(3/4),label:"Portrait · 3:4"},{value:String(21/9),label:"Wide · 21:9"}]}/>;
  return <div className="reference-stack">{ratioControl}<p>Aspect Ratio keeps media proportional as its container changes width. Change the ratio to see the same image cropped to each format.</p><S.AspectRatio ratio={ratio}><img src={sampleMedia} alt="Mountain landscape with a sun and layered ridgelines"/></S.AspectRatio><small>{ratio.toFixed(3)} width / height · object-fit: cover</small></div>;
}

