  const ratioControl = <S.Select label="Aspect ratio" value={String(ratio)} onValueChange={value=>setRatio(Number(value))} options={[{value:String(16/9),label:"Video · 16:9"},{value:String(4/3),label:"Photo · 4:3"},{value:"1",label:"Square · 1:1"},{value:String(3/4),label:"Portrait · 3:4"},{value:String(21/9),label:"Wide · 21:9"}]}/>;
